    return <><div className="mb-4 grid gap-3 sm:grid-cols-3"><label className="text-sm">Search agents<input className={input} value={query} onChange={e => setQuery(e.target.value)} placeholder="Name or assignment" /></label><label className="text-sm">Status<select className={input} value={filter} onChange={e => setFilter(e.target.value)}>{["all", "active", "held", "dead", ...(LIVE ? ["provisioning"] : [])].map(x => <option key={x}>{x}</option>)}</select></label><label className="text-sm">Sort<select className={input} value={sort} onChange={e => setSort(e.target.value)}><option value="name">Name</option><option value="cash">Wallet, highest first</option></select></label></div><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b border-slate-600 text-slate-400"><tr>{["Agent", "Health", "Activity", "Assignment", "Status", "Wallet", "Runway"].map(x => <th className="p-3" key={x}>{x}</th>)}</tr></thead><tbody>{results.map(a => { const m = modelOf(a.id); return <tr key={a.id} className="border-b border-slate-800"><td className="p-3"><div className="flex items-center gap-3">{m && <AgentPortrait id={a.id} name={a.name} band={m.health.band} size={64} />}<div><button className="text-cyan-300 underline" onClick={() => go("Agents", a.id)}>{a.name}</button></div></div></td><td className="p-3">{m ? <HealthTag health={m.health} /> : "—"}</td><td className="p-3 text-xs">{m ? <>{m.placement.activity}<small className="block text-slate-500">{DEPARTMENT[m.placement.department].name}</small></> : "—"}</td><td className="p-3">{a.role}</td><td className="p-3">{a.status}</td><td className="p-3 font-mono">{money(a.cash)}</td><td className="p-3">{LIVE ? runway(a) : <>{Math.floor(a.cash / a.burn)} days</>}</td></tr>; })}</tbody></table>{!results.length && <p className="py-6">No matching agents.</p>}</div></>;
